package asia.aaii.studentstudy;
/** Eight original offline case studies. Fictional, educational, not source-verified real case reports. */
public final class OfflineCaseStudies {
 private OfflineCaseStudies(){}
 public static final class Study{
  public final String title,group,scenario,guide;public final String[] tasks;
  Study(String t,String g,String s,String[] q,String a){title=t;group=g;scenario=s;tasks=q;guide=a;}
 }
 public static final Study[] ALL={
 new Study("Water for a Village","Environment","A rural village has limited clean drinking water. Rainfall is irregular and the nearest reliable source is far from homes. A student team is asked to investigate low-cost ideas. Residents value safety, affordability and easy maintenance.",new String[]{"Identify three stakeholders and their different needs.","Compare rainwater collection with community water filters using cost, reliability and upkeep.","Plan five safe questions for an ethical community survey.","Recommend a small pilot and propose two measurable outcomes."},"Sample direction: assess actual local water quality through qualified testing; budget for filters, storage and maintenance; consult residents and local specialists before making claims about safety."),
 new Study("The Student Book Club","Business","Five students want to start a weekend book-sharing club. They own 40 books, have a small budget for shelves and face the challenge of keeping books in good condition. Some members have limited internet access.",new String[]{"State the service and target users.","Design a simple sign-out policy and privacy-conscious member record.","List fixed and variable costs.","Suggest two indicators of success."},"Sample direction: offer fair lending periods, transparent rules, offline records and a small repair reserve; evaluate uptake and on-time returns."),
 new Study("Responsible AI Homework","Technology","A school introduces an AI study assistant. It can explain concepts and generate original practice questions, but it sometimes makes mistakes and has no access to private class notes unless uploaded by students.",new String[]{"Identify two benefits and two risks.","Describe how students should check the accuracy of an AI answer.","Draft responsible-use classroom guidance.","Create one assessment task that tests reasoning, not copy-paste."},"Sample direction: require attribution, independent verification and student-generated working; avoid uploading personal records and do not treat AI marking as official."),
 new Study("Small Business Bakery","Business","A family bakery sells bread near a school. Sales increase during term time but food waste also rises. The owner wants to test pre-orders and affordable student bundles without reducing food safety.",new String[]{"Identify likely customers and buying factors.","Propose a small pre-order experiment.","Calculate profit if 80 units sell at 2500 each, costing 1600 each to make.","Explain two ethical or operational risks."},"Sample arithmetic: unit contribution 900, total contribution 72000 before fixed costs. Measure leftovers and customer satisfaction in the pilot."),
 new Study("Safer School Commute","Geography","Students travel to school by walking, bicycle and bus. A busy junction has poor visibility at pick-up times. The school wants evidence to identify safe improvements without collecting students' identities.",new String[]{"Suggest two safe observational data methods.","Explain how time of day changes risk.","Draw up a simple comparison table of transport options.","Recommend one improvement and a way to evaluate it."},"Sample direction: anonymised counts, supervised observations, safer crossings, speed management and follow-up measurements; do not send students into traffic to gather data."),
 new Study("School Energy Audit","Science","A classroom uses fluorescent lights, fans and a computer projector. The school wants to reduce electricity use without harming learning conditions. No exact electricity meter readings are available yet.",new String[]{"List four electricity uses.","Explain the difference between power and energy.","Calculate energy for 4 fans rated 50 W running 5 hours.","Design a practical evidence collection plan."},"Sample calculation: total power 200 W=0.2 kW; energy 0.2×5=1.0 kWh. Verify equipment ratings and avoid unsafe electrical work."),
 new Study("Healthy Study Routine","Life Skills","Students report sleeping late before exams and using phones during revision. A peer group wants to create a realistic study routine that includes rest, breaks, exercise and self-reflection.",new String[]{"Identify two potential distractions.","Design a seven-day experiment with optional participation.","Choose two indicators that do not require medical data.","Describe how to adjust a plan after feedback."},"Sample direction: short focused sessions, regular breaks, a stable sleep routine and a supportive opt-in reflection sheet; individual needs vary."),
 new Study("Community Library Project","Education","A neighbourhood wants to share printed and digital learning materials with students who use low-cost phones and sometimes have no connectivity. Volunteers want to respect authors' copyrights.",new String[]{"Define three user requirements.","Compare offline and online access.","Propose a copyright-aware borrowing and permission system.","Design a basic feedback and maintenance workflow."},"Sample direction: licensed/public-domain materials, offline-first navigation, small downloadable files, clear provenance and regular volunteer checks.")
 };
}
